function validate([arr, m, k]) {
  if (!Array.isArray(arr) || arr.length < 2 || arr.length > 100) return 'arr needs 2 to 100 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each value of arr is an integer from 1 to 100.';
  if (!Number.isInteger(m) || m < 1 || m > 100) return 'm is an integer from 1 to 100.';
  if (!Number.isInteger(k) || k < 2 || k > 100) return 'k is an integer from 2 to 100.';
  return null;
}

