function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(60, 100) : int(2, 12);
  const alphabet = large ? (rand() < 0.5 ? 3 : 100) : int(1, 3);
  const arr = Array.from({ length: n }, () => int(1, alphabet));
  const m = large ? int(1, 12) : int(1, 4);
  const k = large ? int(2, 10) : int(2, 4);
  // Half the time, copy one block several times so that true answers and near misses are common.
  if (rand() < 0.6 && m * k <= n) {
    const start = int(0, n - m * k);
    const reps = rand() < 0.5 ? k : k - 1;
    for (let r = 1; r < reps; r++) for (let j = 0; j < m; j++) arr[start + r * m + j] = arr[start + j];
  }
  return [arr, m, k];
}
